{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    dist_list = case['distances']

    # Build list of edges with mutual reachability, canonical order
    edges = []
    seen = set()
    for u, v, d in dist_list:
        if u == v:
            continue
        # canonical order: sort IDs lexicographically
        if u < v:
            a, b = u, v
        else:
            a, b = v, u
        key = (a, b)
        if key in seen:
            continue
        seen.add(key)
        mutual = max(core_dist[a], core_dist[b], d)
        edges.append((mutual, a, b))

    # Sort edges: weight ascending, then a, then b
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find structure
    parent = {}
    rank = {}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    # Initialize all nodes
    for node in nodes:
        parent[node] = node
        rank[node] = 0

    mst_edges = []
    total_weight = 0.0
    for weight, a, b in edges:
        if union(a, b):
            mst_edges.append([a, b, weight])
            total_weight += weight
            if len(mst_edges) == len(nodes) - 1:
                break

    if len(mst_edges) != len(nodes) - 1:
        raise ValueError('Graph is not connected; MST cannot be constructed.')

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
}
